#nullable enable // autogenerated

using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Stats;
using MVZ2Logic;
using MVZ2Logic.Callbacks;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using MVZ2Logic.Modding;
using PVZEngine.Callbacks;
using PVZEngine.Entities;

namespace MVZ2.GameContent.GlobalCallbacks
{
    [ModGlobalCallbacks]
    public class StatsGlobalCallbacks : VanillaGlobalCallbacks
    {
        public override void Apply(Mod mod)
        {
            mod.AddTrigger(LogicLevelCallbacks.POST_USE_ENTITY_BLUEPRINT, PostUseEntityBlueprintCallback);
            mod.AddTrigger(VanillaLevelCallbacks.POST_CONTRAPTION_DESTROY, PostContraptionDestroyCallback);
            mod.AddTrigger(VanillaLevelCallbacks.POST_CONTRAPTION_EVOKE, PostContraptionEvokeCallback);

            mod.AddTrigger(LevelCallbacks.POST_ENEMY_SPAWNED, PostEnemySpawnedCallback);
            mod.AddTrigger(VanillaLevelCallbacks.POST_ENEMY_NEUTRALIZE, PostEnemyNeutralizeCallback);
            mod.AddTriggerFiltered(LevelCallbacks.POST_ENTITY_DEATH, PostEnemyDeathCallback, filter: EntityTypes.ENEMY);
            mod.AddTrigger(LevelCallbacks.POST_GAME_OVER, PostGameOverCallback);
            mod.AddTrigger(LogicLevelCallbacks.POST_LEVEL_RESTART, PostLevelRestartCallback);

            mod.AddTrigger(LevelCallbacks.POST_LEVEL_CLEAR, PostLevelClearCallback);
        }
        private void PostUseEntityBlueprintCallback(LogicLevelCallbacks.PostUseEntityBlueprintParams param, CallbackResultVoid callbackResult)
        {
            var output = param.placeOutput;
            var entity = output.entity;
            if (entity == null)
                return;
            var seed = param.blueprint;
            var definition = param.definition;
            var heldData = param.heldData;
            var level = entity.Level;
            if (level.IsIZombie())
            {
                if (entity.Type == EntityTypes.ENEMY)
                {
                    Global.Saves.AddStat(VanillaStats.CATEGORY_IZ_ENEMY_PLACE, entity.GetDefinitionID(), 1);
                }
            }
            else
            {
                if (entity.Type == EntityTypes.PLANT)
                {
                    Global.Saves.AddStat(VanillaStats.CATEGORY_CONTRAPTION_PLACE, entity.GetDefinitionID(), 1);
                }
            }
        }
        private void PostContraptionDestroyCallback(EntityCallbackParams param, CallbackResultVoid result)
        {
            var entity = param.entity;
            if (entity.Level.IsIZombie())
            {
                Global.Saves.AddStat(VanillaStats.CATEGORY_IZ_CONTRAPTION_DESTROY, entity.GetDefinitionID(), 1);
            }
            else
            {
                Global.Saves.AddStat(VanillaStats.CATEGORY_CONTRAPTION_DESTROY, entity.GetDefinitionID(), 1);
            }
        }
        private void PostContraptionEvokeCallback(EntityCallbackParams param, CallbackResultVoid result)
        {
            var entity = param.entity;
            Global.Saves.AddStat(VanillaStats.CATEGORY_CONTRAPTION_EVOKE, entity.GetDefinitionID(), 1);
        }
        private void PostEnemySpawnedCallback(EntityCallbackParams param, CallbackResultVoid result)
        {
            var entity = param.entity;
            if (!entity.Level.IsIZombie())
            {
                Global.Saves.AddStat(VanillaStats.CATEGORY_ENEMY_SPAWN, entity.GetDefinitionID(), 1);
            }
        }
        private void PostEnemyNeutralizeCallback(EntityCallbackParams param, CallbackResultVoid result)
        {
            var entity = param.entity;
            if (!entity.Level.IsIZombie())
            {
                if (entity.IsFriendlyEntity())
                    return;
                Global.Saves.AddStat(VanillaStats.CATEGORY_ENEMY_NEUTRALIZE, entity.GetDefinitionID(), 1);
            }
        }
        private void PostEnemyDeathCallback(LevelCallbacks.EntityDeathParams param, CallbackResultVoid result)
        {
            var entity = param.entity;
            if (entity.Level.IsIZombie())
            {
                Global.Saves.AddStat(VanillaStats.CATEGORY_IZ_ENEMY_DEATH, entity.GetDefinitionID(), 1);
            }
        }
        private void PostGameOverCallback(LevelCallbacks.PostGameOverParams param, CallbackResultVoid result)
        {
            var killer = param.killer;
            var level = param.level;
            if (level.IsIZombie())
            {
                Global.Saves.AddStat(VanillaStats.CATEGORY_IZ_GAME_OVER, level.StageID, 1);
            }
            else
            {
                if (killer != null)
                {
                    Global.Saves.AddStat(VanillaStats.CATEGORY_ENEMY_GAME_OVER, killer.GetDefinitionID(), 1);
                }
                Global.Saves.AddStat(VanillaStats.CATEGORY_LEVEL_GAME_OVER, level.StageID, 1);
            }
        }
        private void PostLevelClearCallback(LevelCallbackParams args, CallbackResultVoid result)
        {
            var level = args.level;
            int curseCount = level.GetCurseCount();
            if (curseCount > 0)
            {
                var stageID = level.StageID;
                var stat = Global.Saves.GetStat(VanillaStats.CATEGORY_LEVEL_ENABLED_CURSE_COUNT, stageID);
                if (curseCount > stat)
                {
                    Global.Saves.SetStat(VanillaStats.CATEGORY_LEVEL_ENABLED_CURSE_COUNT, stageID, curseCount);
                }
            }
            Global.Saves.AddStat(VanillaStats.CATEGORY_LEVEL_COMPLETED, level.StageID, 1);
        }
        private void PostLevelRestartCallback(LogicLevelCallbacks.LevelRestartArgs args, CallbackResultVoid result)
        {
            var level = args.level;
            var status = args.status;
            if (status != LevelRestartStatus.GameOver)
            {
                Global.Saves.AddStat(VanillaStats.CATEGORY_LEVEL_RESTART, level.StageID, 1);
            }
        }
    }
}
